import sys, json
import pandas as pd
import numpy as np

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---- Totals ----
    tot_rev_tw = df['Revenue_TW'].sum(skipna=True)
    tot_rev_lw = df['Revenue_LW'].sum(skipna=True)
    tot_rev_ly = df['Revenue_LY'].sum(skipna=True)
    tot_units_tw = df['Units_TW'].sum(skipna=True)
    tot_units_lw = df['Units_LW'].sum(skipna=True)
    tot_orders_tw = df['Orders_TW'].sum(skipna=True)
    tot_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(tot_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(float(tot_rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LY",
        "value": round(float(tot_rev_ly), 2),
        "formula": "sum(Revenue_LY)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": float(tot_units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": float(tot_units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": float(tot_orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": float(tot_orders_lw),
        "formula": "sum(Orders_LW)"
    })

    if tot_rev_lw and not np.isnan(tot_rev_lw) and tot_rev_lw != 0:
        tot_wow = (tot_rev_tw - tot_rev_lw) / tot_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(tot_wow), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if tot_rev_ly and not np.isnan(tot_rev_ly) and tot_rev_ly != 0:
        tot_yoy = (tot_rev_tw - tot_rev_ly) / tot_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(tot_yoy), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # ---- Top 3 entities by Rank ----
    top3 = df[df['Rank'].notna()].sort_values('Rank').head(3)
    for _, row in top3.iterrows():
        entity = row['Entity']

        if pd.notna(row['Revenue_TW']):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "TW",
                "value": round(float(row['Revenue_TW']), 2),
                "formula": "Revenue_TW"
            })

        if pd.notna(row['Share_Pct']):
            facts.append({
                "entity": entity, "metric": "share", "period": "TW",
                "value": round(float(row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })

        if pd.notna(row['WoW_Pct']):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "WoW",
                "value": round(float(row['WoW_Pct']), 1),
                "formula": "WoW_Pct"
            })

        if pd.notna(row['YoY_Pct']):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "YoY",
                "value": round(float(row['YoY_Pct']), 1),
                "formula": "YoY_Pct"
            })

    # ---- Biggest movers ----
    wow_valid = df[df['WoW_Pct'].notna()]
    if not wow_valid.empty:
        max_wow_row = wow_valid.loc[wow_valid['WoW_Pct'].idxmax()]
        min_wow_row = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        facts.append({
            "entity": max_wow_row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(max_wow_row['WoW_Pct']), 1),
            "formula": "max(WoW_Pct) across entities"
        })
        facts.append({
            "entity": min_wow_row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(min_wow_row['WoW_Pct']), 1),
            "formula": "min(WoW_Pct) across entities"
        })

    yoy_valid = df[df['YoY_Pct'].notna()]
    if not yoy_valid.empty:
        max_yoy_row = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmax()]
        min_yoy_row = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        facts.append({
            "entity": max_yoy_row['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(float(max_yoy_row['YoY_Pct']), 1),
            "formula": "max(YoY_Pct) across entities"
        })
        facts.append({
            "entity": min_yoy_row['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(float(min_yoy_row['YoY_Pct']), 1),
            "formula": "min(YoY_Pct) across entities"
        })

    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
